    private static List<UUID> parseDeveloperIds() {
        String raw = System.getenv().getOrDefault("SPARTA_DEVELOPER_UUIDS", "");
        if (raw.isEmpty()) return List.of();
        java.util.ArrayList<UUID> ids = new java.util.ArrayList<>();
        for (String part : raw.split(",")) {
            try {
                ids.add(UUID.fromString(part.trim()));
            } catch (IllegalArgumentException ignored) {
            }
        }
        return java.util.Collections.unmodifiableList(ids);
    }

